CREATE TABLE app_user (id bigserial PRIMARY KEY, username varchar(80) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, role varchar(20) NOT NULL CHECK (role IN ('ADMIN','CASHIER')), active boolean NOT NULL DEFAULT true);
CREATE TABLE product (id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, barcode varchar(80) UNIQUE, name varchar(200) NOT NULL, category varchar(120), description text, presentation varchar(120), laboratory varchar(120), purchase_price numeric(14,2) NOT NULL DEFAULT 0 CHECK (purchase_price >= 0), sale_price numeric(14,2) NOT NULL CHECK (sale_price >= 0), minimum_stock integer NOT NULL DEFAULT 0 CHECK (minimum_stock >= 0), active boolean NOT NULL DEFAULT true);
CREATE TABLE supplier (id bigserial PRIMARY KEY, name varchar(200) NOT NULL, phone varchar(60), active boolean NOT NULL DEFAULT true);
CREATE TABLE customer (id bigserial PRIMARY KEY, name varchar(200) NOT NULL, phone varchar(60));
CREATE TABLE purchase (id bigserial PRIMARY KEY, supplier_id bigint REFERENCES supplier, created_by bigint NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now(), total numeric(14,2) NOT NULL CHECK(total >= 0));
CREATE TABLE batch (id bigserial PRIMARY KEY, product_id bigint NOT NULL REFERENCES product, lot varchar(100) NOT NULL, expires_on date NOT NULL, quantity integer NOT NULL CHECK(quantity >= 0), blocked boolean NOT NULL DEFAULT false, UNIQUE(product_id,lot));
CREATE TABLE purchase_line (id bigserial PRIMARY KEY, purchase_id bigint NOT NULL REFERENCES purchase, batch_id bigint NOT NULL REFERENCES batch, quantity integer NOT NULL CHECK(quantity > 0), unit_cost numeric(14,2) NOT NULL CHECK(unit_cost >= 0));
CREATE TABLE sale (id bigserial PRIMARY KEY, request_id uuid NOT NULL UNIQUE, customer_id bigint REFERENCES customer, created_by bigint NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now(), subtotal numeric(14,2) NOT NULL, tax numeric(14,2) NOT NULL, total numeric(14,2) NOT NULL, status varchar(12) NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','VOID')));
CREATE TABLE sale_line (id bigserial PRIMARY KEY, sale_id bigint NOT NULL REFERENCES sale, product_id bigint NOT NULL REFERENCES product, batch_id bigint NOT NULL REFERENCES batch, quantity integer NOT NULL CHECK(quantity > 0), unit_price numeric(14,2) NOT NULL CHECK(unit_price >= 0));
CREATE TABLE payment (id bigserial PRIMARY KEY, sale_id bigint NOT NULL REFERENCES sale, method varchar(30) NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount >= 0));
CREATE TABLE stock_movement (id bigserial PRIMARY KEY, batch_id bigint NOT NULL REFERENCES batch, quantity integer NOT NULL CHECK(quantity <> 0), kind varchar(30) NOT NULL, reference_id bigint, actor_id bigint NOT NULL REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE setting (key varchar(80) PRIMARY KEY, value text NOT NULL);
INSERT INTO setting VALUES ('pharmacy_name','Mi farmacia'),('currency','NIO'),('tax_rate','0');
CREATE TABLE audit_log (id bigserial PRIMARY KEY, actor_id bigint REFERENCES app_user, action varchar(80) NOT NULL, details text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX batch_available_idx ON batch(product_id, expires_on) WHERE quantity > 0 AND NOT blocked;
CREATE INDEX movement_time_idx ON stock_movement(created_at); CREATE INDEX sale_time_idx ON sale(created_at);
